cd /workspace && node -e "
const fs=require('fs');
let raw=fs.readFileSync('/tmp/doctor.json','utf8');
// find first { and last }
const start=raw.indexOf('{');
const end=raw.lastIndexOf('}');
let d; try{ d=JSON.parse(raw.slice(start,end+1)); }catch(e){ console.log('parse fail:',e.message); process.exit(2); }
const checks = Array.isArray(d)? d : (d.checks || d.results || []);
if(!checks.length) console.log('TOP KEYS:', Object.keys(d));
let ok=0,warn=0,err=0,skip=0;
for(const c of checks){
  const s=c.status||'?';
  if(s==='ok')ok++; else if(s==='warn')warn++; else if(s==='error')err++; else skip++;
  if(s!=='ok'){
    console.log(s.toUpperCase().padEnd(8),'|',(c.code||c.name||'?').padEnd(48),'|',String(c.message).slice(0,170));
  }
}
console.log('SUMMARY ok/warn/error/skipped =',ok,warn,err,skip,'total',checks.length);
"
